mapper.select:
SELECT d.id, d.name, d.age, d.sex, d.level_id, d.phone, d.type_id, d.hospital, d.account_id, d.createtime, d.updatetime, l.name AS level_name, t.name AS type_name, a.uname AS uname FROM doctor d LEFT JOIN doctor_level l ON l.id = d.level_id LEFT JOIN treat_type t ON t.id = d.type_id LEFT JOIN account a ON a.id = d.account_id
AND d.name LIKE CONCAT('%', #{name}, '%')
AND d.level_id = #{levelId}
AND d.type_id = #{typeId}
ORDER BY d.id DESC
